    set.cstrike = { total: 26, ll: 4, trail: [2, 9], tp: 'armR', hits: [],                                                   // riposte : revers de la main
      pose: [[0, { armR: 2.4, lean: -0.15 }], [4, { armR: 1.4, lean: 0.25 }], [9, { armR: 0.6, lean: 0.3 }], [26, { armR: 0.45, lean: 0.05 }]] };
