    basico: (m) => IP(m, { yaw: -0.75, lean: 0.15, head: -0.15, armR: [0, 0, 2.0], armL: [0, 0, 1.2], legL: [0, 0, -0.5], legR: [0, 0, -0.3], scarf: -0.5 }),
