        if (ok) { const iw = w * 0.9, ih = iw * LOGO_POSTER_IMG.naturalHeight / LOGO_POSTER_IMG.naturalWidth; g.drawImage(LOGO_POSTER_IMG, (w - iw) / 2, 70, iw, ih); }
        g.fillStyle = '#ffe066'; g.font = 'italic 900 40px Arial Black, Arial'; g.textAlign = 'center'; g.fillText('25 KHEYS', w / 2, h - 110);
        g.fillStyle = '#fff'; g.font = '700 26px Arial'; g.fillText('UN SEUL SURVIVANT', w / 2, h - 66);
