      c.querySelector('.lv').textContent = L.bossFight ? `BOSS · ${I.name}` : `NIVEAU ${i + 1} · ÎLE ${L.island + 1}${L.boss ? ' · ' + I.boss.toUpperCase() : ''}`;
      c.querySelector('.nm').textContent = hidden ? '???' : L.def.name;
      c.querySelector('.tt').textContent = L.soon ? 'PAS ENCORE SORTI · REVIENS PLUS TARD' : hidden ? (L.bossFight && st === 'grey' ? 'TERMINE LES 25 NIVEAUX' : 'KHEY MYSTÈRE') : (L.def.title || '').toUpperCase();
      c.querySelector('.st').textContent = 'Stage : ' + (stg ? stg.name : '');
