      const sg = g.createRadialGradient(sx, 45, 4, sx, 45, 110); sg.addColorStop(0, 'rgba(255,250,210,.95)'); sg.addColorStop(0.25, 'rgba(255,240,170,.5)'); sg.addColorStop(1, 'rgba(255,240,170,0)');
      g.fillStyle = sg; g.fillRect(sx - 110, 0, 220, 100);
      g.fillStyle = '#fff8d8'; g.beginPath(); g.arc(sx, 45, 22, 0, TAU); g.fill();
      for (const c of this.clouds) {
        const x = ((c.x - cx * 0.15 + t * 0.08) % (this.worldW * 0.6) + this.worldW * 0.6) % (this.worldW * 0.6) - 150;
        if (x < -200 || x > vw + 200) continue;
        g.fillStyle = 'rgba(255,255,255,.9)';
        for (let k = 0; k < 4; k++) { g.beginPath(); g.ellipse(x + k * c.w * 0.22, c.y + (k % 2 ? -6 : 0), c.w * 0.2, 11, 0, 0, TAU); g.fill(); }
      }
