      for (const sp of this.bossSpots) if (this.spotVisible(sp.k) && vis(sp.x)) this.node(g, { x: sp.x, y: sp.y, boss: true, bossNode: true }, -1, t, isUnlocked(sp.def.id) ? 'gold' : 'red');
