      const gr = I.k === 1 ? ['#3f9a3a', '#58b648', '#2e7d2e'] : ['#5bbd48', '#7ed35e', '#3f9a3a'];
      poly(I.pts, 0, -6, 0.84, 0.76); g.fillStyle = gr[2]; g.fill();
      poly(I.pts, 0, -10, 0.82, 0.73); g.fillStyle = gr[0]; g.fill();
