      const pt = this.playerPoint(), walking = Math.abs(this.p - this.target) > 1e-3 || (this.spur && this.spur.t !== this.spur.target);
      const hop = walking ? Math.abs(Math.sin((this.spur ? this.spur.t * 3 : this.p) * Math.PI * 4)) * 12 : Math.sin(t * 0.08) * 2.5;
