      const s = c.createBufferSource(); s.buffer = noise; s.playbackRate.value = 0.8 + R() * 0.4;
      const f = c.createBiquadFilter(); f.type = type; f.Q.value = q; f.frequency.setValueAtTime(f0, t); if (f1 && f1 !== f0) f.frequency.exponentialRampToValueAtTime(f1, t + dur);
      const g = c.createGain(); env(g, t, attack, gain, dur);
