        const ac = this.ac;
        if (!this.master) {
          this.master = ac.createGain(); this.master.gain.value = 0;
          this.lp = ac.createBiquadFilter(); this.lp.type = 'lowpass'; this.lp.frequency.value = 18000;
          this.master.connect(this.lp).connect(ac.destination);
          const len = ac.sampleRate * 0.5, buf = ac.createBuffer(1, len, ac.sampleRate), d = buf.getChannelData(0);
          for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
          this.noise = buf;
        }
