      let html;
      if (p) {
        const imp = this.isImp(out);
        html = `<div class="stars"></div><img class="fly" src="${this.online.icon(p.c)}"><h1>${esc(p.n)}</h1><p>a été jeté du balcon.<br><b style="color:${imp ? '#ff4a4a' : '#5ad1ff'}">${esc(p.n)} ${imp ? 'était' : 'n\'était pas'} le Branleur.</b><br><small>${left} Branleur${left > 1 ? 's' : ''} restant${left > 1 ? 's' : ''}.</small></p>`;
      } else html = `<div class="stars"></div><h1>PERSONNE</h1><p>n'a été éjecté (${m.res.tie ? 'égalité' : m.res.none ? 'personne n\'a voté' : 'vote blanc'}).<br><small>${left} Branleur${left > 1 ? 's' : ''} restant${left > 1 ? 's' : ''}.</small></p>`;
      this.$('.meet').style.display = 'none';
