      const cv = w.querySelector('canvas'), g = cv.getContext('2d'), s = Math.min(cv.width / AMG.W, cv.height / AMG.H), ox = (cv.width - AMG.W * s) / 2, oy = (cv.height - AMG.H * s) / 2;
      g.fillStyle = '#0d1020'; g.fillRect(0, 0, cv.width, cv.height);
      for (let z = 0; z < AMG.H; z++) for (let x = 0; x < AMG.W; x++) { const k = this.grid[z * AMG.W + x]; if (!k) continue; g.fillStyle = k === '-' ? '#4a5470' : amgCss(amgShade(AMG_ROOMS[k].c, 0.75)); g.fillRect(ox + x * s, oy + z * s, s + 0.5, s + 0.5); }
      g.font = `900 ${Math.round(s * 0.75)}px "Arial Black",sans-serif`; g.textAlign = 'center'; g.textBaseline = 'middle';
      for (const k in AMG_ROOMS) { const [x0, z0, x1, z1] = AMG_ROOMS[k].r; g.fillStyle = 'rgba(0,0,0,.6)'; g.fillText(AMG_ROOMS[k].n, ox + (x0 + x1 + 1) / 2 * s + 2, oy + (z0 + z1 + 1) / 2 * s + 2); g.fillStyle = '#fff'; g.fillText(AMG_ROOMS[k].n, ox + (x0 + x1 + 1) / 2 * s, oy + (z0 + z1 + 1) / 2 * s); }
      g.fillStyle = '#ff2a2a'; g.beginPath(); g.arc(ox + (AMG_TABLE[0] + 0.5) * s, oy + (AMG_TABLE[1] + 1.4) * s, s * 0.45, 0, TAU); g.fill();
      if (this.inGame()) for (const id of this.myTasks) { if (this.done.has(id)) continue; const tk = AMG_TASKS.find(t => t.id === id); g.fillStyle = '#ffd23a'; g.beginPath(); g.arc(ox + tk.p[0] * s, oy + tk.p[1] * s, s * 0.5, 0, TAU); g.fill(); g.fillStyle = '#000'; g.fillText('!', ox + tk.p[0] * s, oy + tk.p[1] * s + 1); }
      if (this.role === 'imp' && this.inGame()) for (const net of AMG_VENTS) for (const [vx, vz] of net) { g.strokeStyle = '#ff6a6a'; g.lineWidth = 3; g.strokeRect(ox + vx * s - s * 0.4, oy + vz * s - s * 0.3, s * 0.8, s * 0.6); }
      const mx = ox + this.me.x / AMG.CS * s, mz = oy + this.me.z / AMG.CS * s;
