        if (mode === 0) { hue = ((i + j) * 0.07 + beat * 0.05) % 1; l = ((i + j + Math.floor(beat)) % 2) ? 0.55 : 0.12; }
        else if (mode === 1) { const d = Math.hypot(i - NX / 2 + 0.5, j - NZ / 2 + 0.5); hue = (d * 0.08 + beat * 0.02) % 1; l = 0.1 + 0.5 * Math.max(0, Math.cos(d * 1.2 - beat * Math.PI)); }
        else { hue = (j * 0.11 + Math.floor(beat / 2) * 0.13) % 1; l = (i === Math.floor(beat * 2) % NX || j === Math.floor(beat) % NZ) ? 0.6 : 0.1 + 0.08 * pulse; }
        col.setHSL(hue, 0.9, l); this.tiles.setColorAt(k++, col);
