    const c = document.createElement('canvas'), w = o.w || 512, h = o.h || 128; c.width = w; c.height = h; const g = c.getContext('2d');
    if (o.bg) { g.fillStyle = o.bg; g.fillRect(0, 0, w, h); if (o.border) { g.strokeStyle = o.border; g.lineWidth = 10; g.strokeRect(5, 5, w - 10, h - 10); } }
    let fs = o.fs || 80; g.font = `italic 900 ${fs}px "SSK Rodin","Arial Black",sans-serif`; while (g.measureText(txt).width > w - 30 && fs > 20) { fs -= 4; g.font = `italic 900 ${fs}px "SSK Rodin","Arial Black",sans-serif`; }
    g.textAlign = 'center'; g.textBaseline = 'middle';
    if (o.stroke) { g.lineWidth = o.sw || 12; g.strokeStyle = o.stroke; g.lineJoin = 'round'; g.strokeText(txt, w / 2, h / 2 + 4); }
    if (o.glow) { g.shadowColor = o.glow; g.shadowBlur = 24; }
    g.fillStyle = o.col || '#fff'; g.fillText(txt, w / 2, h / 2 + 4);
