      for (let k = 0; k < 40; k++) { const s2 = new T.Sprite(new T.SpriteMaterial({ map: cloudTex, fog: false, transparent: true, opacity: 0.95, depthWrite: false })); s2.scale.set(14 + (k % 3) * 4, 6 + (k % 2) * 2, 1); s2.position.set(k * 4.2 - 20, 2.5 + (k % 3) * 0.8, -70); sc.add(s2); }
