          for (const [px, py] of P) for (const ox of [-256, 0, 256]) for (const oy of [-256, 0, 256]) { const dd = (x - px - ox) ** 2 + (y - py - oy) ** 2; if (dd < d1) { d2 = d1; d1 = dd; } else if (dd < d2) d2 = dd; }
          const e = Math.sqrt(d2) - Math.sqrt(d1), v = e < 3 ? 255 : 210 + Math.min(45, e);
