      const m = new T.Mesh(g, new T.MeshStandardMaterial({ map: this.pathTex(), roughness: 1, side: T.DoubleSide, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 }));
      m.receiveShadow = true; this.sc3.add(m);
