      grp.position.set(mX(n.x), this.groundAt(n.x, n.y), mZ(n.y));
      const base = new T.Mesh(new T.CylinderGeometry(R + 0.1, R + 0.16, 0.16, 28), new T.MeshStandardMaterial({ color: 0x3a2412, roughness: 0.8 })); base.position.y = 0.08; base.castShadow = base.receiveShadow = true; grp.add(base);
