        const star = new T.Mesh(new T.ExtrudeGeometry(st, { depth: 0.08, bevelEnabled: false }), new T.MeshStandardMaterial({ color: 0xffe066, emissive: 0x5a4400, metalness: 0.4, roughness: 0.3 }));
