      const lbl = new T.Sprite(new T.SpriteMaterial({ map: txtTex(n.bossNode ? (n.bonus ? 'BONUS' : 'BOSS') : String(i + 1), { stroke: '#2a1a0c', col: n.bossNode ? '#ffe066' : '#fff', fs: 96, w: 256, h: 128 }), depthWrite: false, transparent: true }));
      lbl.scale.set(0.9, 0.45, 1); lbl.position.set(0, 0.25, R + 0.55); grp.add(lbl);
      grp.userData.topM = topM; grp.userData.ring = ring;
