      this.tvScore = new T.Mesh(new T.PlaneGeometry(4.8, 0.45), new T.MeshBasicMaterial({ map: this.scoreTex, transparent: true }));
      this.tvScore.rotation.y = Math.PI / 2; this.tvScore.position.set(-13.55, 1.5, -6.5); this.tvScore.visible = false; sc.add(this.tvScore);
      // ---- fléchettes (mur du sud, à droite de la porte de la boîte)
