        const { g: mh } = lemmGrab('modos', { pick: (o, pal, hx, m) => { const p = new T.Vector3().setFromMatrixPosition(lemmRel(o, m.head)); return p.length() < 0.62 && Math.abs(p.z) < 0.48; } });
        let screen = null; mh.traverse(o => { if (o.isMesh && o.material && o.material.map && o.geometry.parameters && Math.abs(o.geometry.parameters.width - 0.72) < 1e-3) screen = o; });
        const bb = new T.Box3().setFromObject(mh), bc = bb.getCenter(new T.Vector3()), bs = bb.getSize(new T.Vector3());
        const k = Math.min(sz.z * 1.25 / bs.z, sz.y * 1.15 / bs.y); mh.scale.setScalar(k); mh.position.set(c.x - bc.x * k, c.y - bc.y * k, c.z - bc.z * k);
