            x.fillStyle = 'rgba(255,255,255,.08)'; for (let y = 0; y < 240; y += 4) x.fillRect(0, y, 320, 1);
            if (im) { const s = Math.min(300 / im.naturalWidth, 230 / im.naturalHeight); x.drawImage(im, 160 - im.naturalWidth * s / 2, 238 - im.naturalHeight * s, im.naturalWidth * s, im.naturalHeight * s); }
            x.fillStyle = '#ff3b3b'; x.font = '900 22px Arial'; x.fillText('● REC', 12, 28); tex.needsUpdate = true;
