        const h = new T.Group(); h.position.set(c.x - sz.x * 0.05, S.max.y - sz.y * 0.14, c.z); h.rotation.z = 0.25; g.add(h);
        const rim = add(h, new T.TorusGeometry(r, r * 0.28, 8, 20), M(0xffffff), 0, 0, 0, true, 1.06); rim.rotation.x = Math.PI / 2;
        add(h, new T.ConeGeometry(r * 0.95, r * 2.2, 16), M(0xd8242e), -r * 0.25, r * 0.95, 0, true, 1.05).rotation.z = 0.55;
