  // ---- calendrier : on se fie à l'heure du serveur dès qu'on est connecté
  REL_CLOCK = () => REL_FAKE || NET.now();
  // remet la grille à jour (kheys sortis + boss battus et sortis), renvoie les nouveaux venus
  function rosterSync() {
    const before = new Set(ROSTER.map(d => d.id));
    const ks = ALL_KHEYS.filter(d => isOwned(d.id)), bs = BOSSES.filter(d => d.build && isUnlocked(d.id) && isReleased(d.id));
    ROSTER.length = 0; ROSTER.push(...ks, ...bs, ROSTER_RANDOM);
    AVAILABLE.length = 0; AVAILABLE.push(...ROSTER.filter(r => r.build));
    return ROSTER.filter(d => d.id && d.build && !before.has(d.id));
  }
