    const c = new T.Mesh(new T.CylinderGeometry(0.2, 0.2, 0.05, 18), kitMat(0xffd23a, { emissive: 0x6a4a00, emissiveIntensity: 0.5 })); c.rotation.x = Math.PI / 2; g.add(c);
