    x.fillStyle = '#f6efdc'; x.beginPath(); x.arc(128, 128, 120, 0, TAU); x.fill();
    x.lineWidth = 12; x.strokeStyle = '#5a3a1e'; x.stroke(); x.lineWidth = 3; x.strokeStyle = '#d8b050'; x.beginPath(); x.arc(128, 128, 110, 0, TAU); x.stroke();
