                p.r = 0.9; halo.scale.setScalar(0.9 + Math.sin(p.age * 0.8) * 0.12); p.h = p.age >= 28 ? { dmg: 6, ang: 55, bkb: 36, kbg: 70 } : { dmg: 1, ang: 80, bkb: 12, kbg: 5 };
