      if (code === 'Escape') { wait = null; render(); return true; }
      if (wait.pad) return true;
      const m = KEYMAP[tab];
      for (const a of ACTIONS) m[a] = m[a].filter(c => c !== code);                    // une touche = une seule action
      for (const a of ACTIONS) if (!m[a].length) m[a] = KEYMAP_DEF[tab][a].filter(c => !ACTIONS.some(b => m[b].includes(c))).slice(0, 1);
      m[wait.a] = [code];
