    const key = new T.DirectionalLight(0xffffff, 0.7); key.position.set(5, 10, 14); s.add(key);
    const purple = new T.PointLight(0x9146ff, 1.6, 40); purple.position.set(0, 6, 6); s.add(purple); A.purple = purple;

    // --- Fond de la page Twitch (très grand, sombre)
    const page = new T.Mesh(new T.PlaneGeometry(400, 220), basic({ color: 0x0e0e10, fog: false })); page.position.set(0, 10, -60); s.add(page);

    // --- La page : en-tête, lecteur vidéo, infos de la chaîne, chat
    const W = 2048, H = 1152, pc = mkC(W, H), g = pc.getContext('2d');
    // Le contenu du live : Korochiku joue à… Super Smash Kheys
    const drawStream = (gg, x, y, w, h, t) => {                     // l'image du live (« Stream starting soon »), en plein lecteur
      gg.fillStyle = '#000'; gg.fillRect(x, y, w, h);
      const im = TW_LIVE_IMG;
      if (im.complete && im.naturalWidth) { const k = Math.max(w / im.naturalWidth, h / im.naturalHeight), iw = im.naturalWidth * k, ih = im.naturalHeight * k; gg.save(); gg.beginPath(); gg.rect(x, y, w, h); gg.clip(); gg.drawImage(im, x + (w - iw) / 2, y + (h - ih) / 2, iw, ih); gg.restore(); }
    };
