      g.fillStyle = TW_P; g.beginPath(); g.moveTo(28, 14); g.lineTo(70, 14); g.lineTo(70, 44); g.lineTo(58, 56); g.lineTo(46, 56); g.lineTo(38, 64); g.lineTo(38, 56); g.lineTo(28, 56); g.closePath(); g.fill();
      g.fillStyle = TW_PANEL; g.fillRect(42, 24, 6, 14); g.fillRect(56, 24, 6, 14);
      g.font = `700 26px ${FONT}`; g.fillStyle = '#efeff1'; g.textAlign = 'left'; g.fillText('Suivis', 100, 46); g.fillText('Parcourir', 210, 46);
      g.fillStyle = '#26262c'; rrect(g, 720, 16, 560, 40, 8); g.fill(); g.fillStyle = '#8a8a93'; g.font = `600 22px ${FONT}`; g.fillText('Rechercher', 740, 44);
      g.fillStyle = TW_P; rrect(g, 1800, 14, 150, 42, 8); g.fill(); g.fillStyle = '#fff'; g.font = `800 22px ${FONT}`; g.fillText("S'inscrire", 1822, 43);
      g.fillStyle = '#b48cff'; g.beginPath(); g.arc(1990, 35, 20, 0, TAU); g.fill();
      // lecteur vidéo
