      g.fillStyle = '#eb0400'; rrect(g, L.vidX + 20, L.vidY + 20, 86, 34, 5); g.fill(); g.fillStyle = '#fff'; g.font = `800 22px ${FONT}`; g.fillText('LIVE', L.vidX + 36, L.vidY + 45);
      g.fillStyle = 'rgba(0,0,0,.6)'; rrect(g, L.vidX + 116, L.vidY + 20, 150, 34, 5); g.fill(); g.fillStyle = '#ff8a8a'; g.fillText('● ' + (1337 + Math.floor(t / 90) % 50), L.vidX + 128, L.vidY + 45);
      // infos de la chaîne sous la vidéo
