      g.fillStyle = TW_P; g.beginPath(); g.arc(L.vidX + 52, iy + 52, 46, 0, TAU); g.fill();
      g.fillStyle = '#eb0400'; rrect(g, L.vidX + 22, iy + 88, 60, 22, 4); g.fill(); g.fillStyle = '#fff'; g.font = `800 15px ${FONT}`; g.fillText('LIVE', L.vidX + 34, iy + 105);
      g.fillStyle = '#efeff1'; g.font = `800 34px ${FONT}`; g.fillText('korochiku', L.vidX + 116, iy + 40);
      g.fillStyle = '#efeff1'; g.font = `600 24px ${FONT}`; g.fillText('🔴 TOURNOI SMASH KHEYS · NNN · on chope tout le monde !grab', L.vidX + 116, iy + 76);
      g.fillStyle = '#bf94ff'; g.fillText('Super Smash Kheys', L.vidX + 116, iy + 108); g.fillStyle = '#adadb8'; g.fillText('Français · Combat · Kheys', L.vidX + 380, iy + 108);
      // chat
      g.fillStyle = TW_PANEL; g.fillRect(L.chatX - 8, L.head, W - L.chatX + 8, H - L.head);
      g.fillStyle = '#efeff1'; g.font = `800 22px ${FONT}`; g.textAlign = 'center'; g.fillText('CHAT DU STREAM', L.chatX + L.chatW / 2, L.head + 40); g.textAlign = 'left';
      g.fillStyle = '#2e2e35'; g.fillRect(L.chatX, L.head + 60, L.chatW, 2);
      g.save(); g.beginPath(); g.rect(L.chatX, L.head + 64, L.chatW, H - L.head - 160); g.clip();
