      g.fillStyle = TW_P; rrect(g, L.chatX + L.chatW - 104, H - 34, 96, 30, 6); g.fill(); g.fillStyle = '#fff'; g.font = `800 18px ${FONT}`; g.fillText('Chat', L.chatX + L.chatW - 76, H - 13);
      // alertes d'abonnement en haut du lecteur
