  const COP_LINES = ['Police ! On ne bouge plus !', 'Le NNN, c\'est sacré !', 'Tu croyais craquer en douce ?', 'Un vrai khey résiste !', 'Pense à tes frères du topic !', 'Tentative de Nut, mon gars…', 'Novembre, c\'est pas fini !'];
