    const hc = cAdd(head, new T.SphereGeometry(0.22, 14, 8, 0, TAU, 0, Math.PI * (pal.bald ? 0.18 : 0.45)), mH, -0.01, 0.02, 0, 1.03); hc.rotation.z = 0.35;
