          const carpet = hubCanvas(256, 256, (g, w, h) => { g.fillStyle = '#4a0a26'; g.fillRect(0, 0, w, h); for (let i = 0; i < 60; i++) { g.strokeStyle = `rgba(255,120,200,${Math.random() * 0.15})`; g.beginPath(); g.arc(Math.random() * w, Math.random() * h, 10 + Math.random() * 30, 0, TAU); g.stroke(); } });
