          box(1.0, 1.15, 9, wood, 191.6, 0.575, -38.5); box(1.3, 0.07, 9.2, top, 191.6, 1.18, -38.5); box(0.04, 0.05, 9, edge, 192.12, 0.12, -38.5);
          solid(190, -43.1, 192.2, -33.9);
          box(0.2, 3.2, 9, std(0x22101a), 190.2, 2.4, -38.5);
          const bc = [0x2a7a3a, 0x7a2a1a, 0xd8c060, 0x1a3a7a, 0xe8e8f0, 0x8a3ab0, 0xff3ca0];
          for (let r2 = 0; r2 < 2; r2++) { box(0.4, 0.05, 8.6, std(0x3a2a20), 190.45, 1.8 + r2 * 0.9, -38.5); for (let i = 0; i < 14; i++) { const c = bc[(i + r2 * 3) % bc.length], hh = 0.4 + (i % 3) * 0.08; const bt = new T.Mesh(new T.CylinderGeometry(0.08, 0.09, hh, 8), new T.MeshStandardMaterial({ color: c, emissive: c, emissiveIntensity: 0.3, transparent: true, opacity: 0.9 })); bt.position.set(190.45, 1.83 + r2 * 0.9 + hh / 2, -42.4 + i * 0.6); sc.add(bt); } }
          neon('BAR', '#ff9ad0', 2.6, 0.8, 190.35, 4.3, -38.5, Math.PI / 2);
          for (const z of [-42, -40, -38, -36]) { const st = new T.Mesh(new T.CylinderGeometry(0.28, 0.28, 0.08, 14), std(0xff3ca0, { roughness: 0.5 })); st.position.set(192.7, 0.82, z); sc.add(st); box(0.05, 0.8, 0.05, std(0x999999, { metalness: 0.8 }), 192.7, 0.4, z); }
