        for (const k in this.myVeh) { const v = this.myVeh[k]; sc.add(v.mesh); this.parkVeh(k, ...v.home); v.tag = new T.Sprite(new T.SpriteMaterial({ map: tagTex('', '#ffd979'), depthWrite: false, transparent: true })); v.tag.scale.set(2.6, 0.49, 1); sc.add(v.tag); v.tagTxt = null; }
        // objets posés (bananes) et confettis
