        if (zn.id === 'strip-go') { m.x = STRIP_PODIUM[0]; m.z = STRIP_PODIUM[1]; m.r = -Math.PI / 2; m.a = 'strip'; this.freeze = true; this.stripT = 0; this.avatar.say('À moi la scène !'); SFX.ui('pick'); return true; }
        if (zn.id === 'strip-stop') { m.a = 'idle'; m.x = STRIP_PODIUM[0]; m.z = -43.0; this.freeze = false; return true; }
        if (zn.id === 'priv-next') { this.privN = (this.privN || 0) + 1; SFX.ui('move'); return true; }
