        if (zn.id === 'pc') { const p = PCS[zn.pc]; this.pcI = zn.pc; m.x = p.x; m.z = p.z; m.r = Math.PI / 2; m.a = 'pc'; m.sy = 0.42; m.sk = 'wc'; this.drawPc(this.pcScreens[zn.pc], 'topic'); SFX.sit(); return true; }
        if (zn.id === 'pc-stand') { m.a = 'idle'; m.z += 0.9; if (this.pcI != null) this.drawPc(this.pcScreens[this.pcI], 'idle'); this.pcI = null; return true; }
        if (zn.id === 'pc-nut') { this.startNut(); return true; }
