      this.fighters = [new Fighter(this, 0, { ...palFor(me, 0, myC), keep: true }, me), new Fighter(this, 1, mirror ? { ...palFor(op, 1, myC === 1 ? 0 : 1), keep: true } : { ...palFor(op, 0), ui: PALETTES[1].ui, keep: true }, op)];
      this.story.level = i; this.story.pos = i; storySave(this.story);
