      const me = AVAILABLE.find(x => x.id === this.story.char) || AVAILABLE[0], mirror = me === d;
      this.fighters.forEach(f => f.dispose());
      const myC = this.story.col || 0;
      this.fighters = [new Fighter(this, 0, { ...palFor(me, 0, myC), keep: true }, me), new Fighter(this, 1, mirror ? { ...palFor(d, 1, myC === 1 ? 0 : 1), keep: true } : { ...palFor(d, 0), ui: PALETTES[1].ui, keep: true }, d)];
      this.story.bossK = k;
      this.cpu = true;
