  // =====================================================================
  //  EN LIGNE : pas de « lag »
  //   1. Les effets visuels n'utilisent plus le tirage du combat (Math.random → tirage à part)
  //   2. Quand on rattrape plusieurs images d'un coup, on ne redessine/repose qu'à la dernière
  //   3. Rythme lissé : si les touches de l'autre arrivent juste à temps, on ralentit à peine au lieu de geler
  //   4. Ping mesuré juste avant le combat (salon, prêt) pour régler le délai au plus juste
  //   5. Résolution adaptative si l'ordinateur rame
  // =====================================================================
  {
    const VIS_RAND = () => DMath.rawRandom();
    const vis = (fn) => { const s = Math.random; Math.random = VIS_RAND; try { return fn(); } finally { Math.random = s; } };
    V91.vis = vis;
    const FXP = FX.prototype, sp0 = FXP.spark, rg0 = FXP.ring;
    FXP.spark = function (x, y, c, n, s) { if (this.off) return; return vis(() => sp0.call(this, x, y, c, n, s)); };
    FXP.ring = function (x, y, c, s, l) { if (this.off) return; return rg0.call(this, x, y, c, s, l); };
    const GP = Game.prototype, say0 = GP.say;
    GP.say = function (f, txt, big, life) { if (this.fx && this.fx.off) return; return say0.call(this, f, txt, big, life); };
    // les visuels du pas de simulation en ligne (appelés une seule fois par image affichée)
    GP.netVisuals = function (n = 1) {
      vis(() => {
        for (const f of this.fighters) f.sync(this.tick);
        for (let k = 0; k < Math.min(n, 4); k++) this.fx.update();
        this.updateBubbles();
        this.updateCamera();
        if (!this.tvSpect) { this.updateHUD(); this.updateDebug(); }
      });
    };
    // NetMatch.pump : rythme lissé + visuels groupés
    const NP = NetMatch.prototype;
    NP.pump = function (dt) {
      if (this.ended) return;
      const g = this.g;
      if (!this.started) {
        const left = this.m.at - NET.now();
        if (left > 0) { g.netWaitBanner(Math.ceil(left / 1000)); return; }
        this.started = true; this.acc = 0; this.startedAt = performance.now();
      }
      let rate = 1;
      if (this.me >= 0) {
        let buf = Infinity;
        for (let i = 0; i < this.N; i++) if (i !== this.me && !this.sl[i].cpu && this.drop[i] === Infinity) buf = Math.min(buf, this.known[i] - this.F);
        if (buf !== Infinity) { if (buf < 1) rate = 0.86; else if (buf < 2) rate = 0.94; else if (buf > this.D + 2) rate = 1.05; }
        this.buf = buf;
      }
      this.acc = Math.min(this.acc + dt * rate, 200);
      let n = 0, stalled = false;
      g.netFast = true;
      try {
        while (this.acc >= STEP && n < 8 && !this.ended) {
          if (!this.canStep(this.F)) { stalled = true; break; }
          this.sample(this.F + this.D);
          this.simulate(this.F);
          this.F++; this.acc -= STEP; n++;
        }
      } finally { g.netFast = false; }
      if (n && !this.ended) g.netVisuals(n);
      if (stalled) this.stallMs += dt; else if (n) this.stallMs = 0;
      g.netStallInfo(this.stallMs > 600 ? this.missing(this.F) : null, this.stallMs, this.desync);
    };
    // ping frais : en entrant dans un salon et en se déclarant prêt
    const OP = Online.prototype;
    for (const k of ['joinRoom', 'createRoom']) { const o = OP[k]; if (o) OP[k] = function (...a) { const r = o.apply(this, a); NET.measurePing && NET.measurePing().then(() => { if (this.rid && NET.isKept(`rooms/${this.rid}/p/${NET.uid}`)) NET.patch(`rooms/${this.rid}/p/${NET.uid}`, { pg: NET.ping || 80 }); }).catch(() => {}); return r; }; }
    const ia0 = OP.inputDelay;
    OP.inputDelay = function (pings) { const p = pings.map(x => clamp(+x || 80, 10, 600)).sort((a, b) => b - a); const lat = ((p[0] || 80) + (p[1] || p[0] || 80)) / 2; return clamp(Math.ceil((lat + 38) / STEP) + 1, 4, 14); };
    // résolution adaptative : si on descend sous ~45 images/s, on baisse la finesse de l'image (et on remonte quand ça va mieux)
    const lp0 = GP.loop;
    GP.loop = function (now) {
      const dt = now - (this.last || now);
      const r = this.renderer;
      if (r && dt > 0 && dt < 250 && (this.mode === 'play' || this.mode === 'hub' || this.mode === 'among')) {
        this._ft = this._ft == null ? dt : this._ft * 0.95 + dt * 0.05;
        const maxPR = Math.min(window.devicePixelRatio || 1, 2), pr = r.getPixelRatio();
        if (++this._prT > 90) {
          this._prT = 0;
          if (this._ft > 22 && pr > 0.75) { r.setPixelRatio(Math.max(0.75, pr - 0.25)); this.onResize(); }
          else if (this._ft < 15.5 && pr < maxPR) { r.setPixelRatio(Math.min(maxPR, pr + 0.25)); this.onResize(); }
        }
      }
      return lp0.call(this, now);
    };
    GP._prT = 0;
  }
