    const rng = DMath.makeRng((day * 2654435761) >>> 0), pool = V93_DAILY.slice(), list = [];
    for (let i = 0; i < 3; i++) list.push(pool.splice(Math.floor(rng() * pool.length), 1)[0]);
    const chars = AVAILABLE.filter(d => !d.boss), cd = chars.length ? chars[day % chars.length] : null;
    return { S, cd, list: list.map(d => ({ ...d, t: d.t.replace('{c}', cd ? cd.name : 'ton khey'), v: Math.min(d.n, S.p[d.id] || 0), done: (S.p[d.id] || 0) >= d.n, got: !!S.c[d.id] })) };
