        for (const d of S.dust) { d.ph = (d.ph + dt * 0.8) % 1; d.s.position.set((A.vr() - 0.5) * 6, 0.4 + d.ph * 2, S.bz - 2.5 - d.ph * 4); d.s.material.opacity = 0.6 * (1 - d.ph); }
        const fz = A.me >= 0 ? S.d[A.me] : Math.max(...S.d);
