        for (let i = 0; i < 4; i++) if (i !== A.me) { const l = A.live(i), av = A.av[i]; if (l !== av._l) { av._l = l; S.btn[i].scale.y = 0.4; av._sh = 0.5; } av._sh = Math.max(0, (av._sh || 0) - dt); }
