      const pv = kpCvTex(64, 64, (g) => { g.fillStyle = '#8a6a4a'; g.fillRect(0, 0, 64, 64); g.fillStyle = '#7a5a3a'; g.fillRect(0, 0, 64, 6); g.fillRect(0, 32, 64, 6); }); pv.wrapS = pv.wrapT = T.RepeatWrapping; pv.repeat.set(16, 16);
