            const e = document.createElement('div'); e.className = 'sk-kxm'; e.innerHTML = '<span></span><i><b></b></i>'; c.el.appendChild(e);
            c.kxm = e; c.kxmT = e.firstChild; c.kxmB = e.querySelector('b'); c.kxmS = '';
