    const dance = []; for (let k = 0; k <= 12; k++) dance.push([6 + k * 5, k % 2 ? { armR: 2.5, armL: -0.7, head: 0.35, legL: 0.5, legR: -0.1, lean: -0.05 } : { armR: -0.6, armL: 2.5, head: -0.35, legL: 0.1, legR: -0.5, lean: 0.12 }]);
