          if (fr >= 12 && fr <= 15) { kitStrike(f, G, f.x + f.facing * 1.45, f.y + 1.25, 0.5, { dmg: 11, ang: 40, bkb: 32, kbg: 70, col: 0xd8202e }, f.hitList); kitStrike(f, G, f.x + f.facing * 0.7, f.y + 1.35, 0.5, { dmg: 6, ang: 45, bkb: 22, kbg: 40 }, f.hitList); }
          kxEnd(f, m, fr);
